function Dashboard({stats,setPage,profile}:any){
 const cards:any[]=[['Unidades',stats.units,Building2,'units'],['Moradores',stats.residents,Users,'residents'],['Encomendas',stats.packages,Package,'packages'],['Visitantes',stats.visitors,DoorOpen,'visitors']];
 const metrics:any[]=[['Moradores',stats.residents,Users,'residents'],['Encomendas',stats.packages,Package,'packages'],['Visitantes',stats.visitors,DoorOpen,'visitors'],['Reservas',stats.reservations,CalendarDays,'reservations'],['Ocorrências',stats.occurrences,AlertTriangle,'occurrences']];
 const max=Math.max(1,...metrics.map(x=>Number(x[1])||0));
 return <><div className="welcome-banner"><div><span className="eyebrow">PORTO FRANKFURT · PAINEL ADMINISTRATIVO</span><h2>Olá, {profile?.full_name?.split(' ')[0]||'bem-vindo'} 👋</h2><p>A visão completa da operação do seu condomínio, em um só lugar.</p><div className="welcome-meta"><span><Shield size={14}/> Gestão segura</span><span><Building2 size={14}/> 15 blocos</span><span><Activity size={14}/> Indicadores atualizados</span></div></div><div className="welcome-art"><Building2 size={76}/><span>PORTO FRANKFURT</span></div></div>
 <div className="stats-grid">{cards.map(([label,value,Icon,key])=><button className="stat-card" key={key} onClick={()=>setPage(key)}><div className="stat-top"><span>{label}</span><i><Icon size={19}/></i></div><strong>{value}</strong><small>{key==='units'?'Unidades cadastradas':'Registros no sistema'}</small><div className="stat-link">Ver detalhes <ArrowUpRight size={14}/></div></button>)}</div>
 <div className="dashboard-columns dashboard-main-grid"><div className="content-card operational-card"><div className="section-card-head"><div><b>Visão operacional</b><small>Volume atual por módulo · dados do sistema</small></div><ChartNoAxesCombined size={19}/></div><div className="operational-list">{metrics.map(([name,value,Icon,key])=><button className="operational-row" key={key} onClick={()=>setPage(key)}><span className="operational-icon"><Icon size={17}/></span><span className="operational-name">{name}</span><span className="operational-track"><i style={{width:Math.max(3,(Number(value)||0)/max*100)+'%'}}/></span><b>{value}</b><ChevronRight size={15}/></button>)}</div><div className="operational-foot"><span>Indicadores calculados a partir dos registros disponíveis.</span><button className="text-link" onClick={()=>setPage('reports')}>Abrir relatórios →</button></div></div>
 <div className="content-card structure-card"><div className="section-card-head"><div><b>Estrutura do condomínio</b><small>Organização física</small></div><Building2 size={19}/></div><div className="structure-illustration"><div className="building-symbol"><Building2 size={43}/><span>PF</span></div><div><strong>15</strong><small>Blocos residenciais</small></div></div><div className="structure-summary"><div><strong>5</strong><span>Andares</span></div><div><strong>4</strong><span>Unidades/andar</span></div><div><strong>300</strong><span>Apartamentos</span></div></div><button className="structure-link" onClick={()=>setPage('units')}>Explorar mapa de unidades <ArrowUpRight size={15}/></button></div></div>
 <div className="dashboard-lower-grid"><div className="content-card"><div className="section-card-head"><div><b>Ações rápidas</b><small>Atalhos para as tarefas mais comuns.</small></div><Command size={18}/></div><div className="quick-grid">{[['Cadastrar morador',Users,'residents'],['Registrar encomenda',Package,'packages'],['Registrar visitante',DoorOpen,'visitors'],['Criar comunicado',MessageSquare,'announcements'],['Nova ocorrência',AlertTriangle,'occurrences'],['Gerenciar reservas',CalendarDays,'reservations']].map(([name,Icon,key]:any)=><button key={key} onClick={()=>setPage(key)}><Icon size={19}/><span>{name}</span><ArrowUpRight size={13}/></button>)}</div></div><div className="content-card dashboard-notice-card"><div className="section-card-head"><div><b>Central de acompanhamento</b><small>Informações e controles</small></div><Bell size={18}/></div><button className="notice-link" onClick={()=>setPage('packages')}><span className="notice-icon"><Package size={18}/></span><span><b>Encomendas</b><small>{stats.packages} registro(s) no sistema</small></span><ChevronRight size={16}/></button><button className="notice-link" onClick={()=>setPage('occurrences')}><span className="notice-icon"><AlertTriangle size={18}/></span><span><b>Ocorrências</b><small>{stats.occurrences} registro(s) no sistema</small></span><ChevronRight size={16}/></button><button className="notice-link" onClick={()=>setPage('announcements')}><span className="notice-icon"><MessageSquare size={18}/></span><span><b>Comunicados</b><small>Acesse os avisos do condomínio</small></span><ChevronRight size={16}/></button></div></div>
 <div className="bottom-insight"><Shield size={19}/><div><b>Segurança e privacidade</b><p>As informações exibidas respeitam o acesso do usuário e as políticas de segurança do banco de dados.</p></div></div></>;
}
function DataTable({page,rows,onPicked,onDecision}:any){const cols:any={residents:['profiles.full_name','profiles.email','profiles.phone','resident_type','apartments.block','apartments.number'],packages:['recipient_name','carrier','tracking_code','received_at','status'],visitors:['visitor_name','vehicle_plate','created_at','status'],reservations:['common_areas.name','apartments.block','apartments.number','starts_at','ends_at','status','purpose'],occurrences:['title','category','created_at','status'],announcements:['title','category','is_published','created_at'],documents:['title','category','created_at'],vehicles:['plate','make','model','color','apartments.block','apartments.number'],common_areas:['name','description'],finance:['description','amount','type','due_date','status'],parking:['space_code','status','location_description','apartments.block','apartments.number','vehicles.plate']};const keys=cols[page]||Object.keys(rows[0]||{}).filter(k=>!['id','condominium_id','created_by','updated_at'].includes(k)).slice(0,6);const get=(o:any,k:string)=>k.split('.').reduce((v,x)=>v?.[x],o);return <div className="table-scroll"><table><thead><tr>{keys.map((k:string)=><th key={k}>{k.split('.').pop().replaceAll('_',' ')}</th>)}{(page==='packages'||page==='reservations')&&<th>Ação</th>}</tr></thead><tbody>{rows.map((r:R,i:number)=><tr key={r.id||i}>{keys.map((k:string)=><td key={k}>{k==='status'?<span className={'status-pill '+(['vacant','approved','picked_up','resolved'].includes(get(r,k))?'good':'warn')}>{status(get(r,k))}</span>:['created_at','received_at','reservation_date','due_date'].includes(k)?date(get(r,k)):['starts_at','ends_at'].includes(k)?new Date(get(r,k)).toLocaleString('pt-BR'):k==='is_published'?(get(r,k)?'Publicado':'Rascunho'):String(get(r,k)??'—')}</td>)}{page==='packages'&&<td>{r.status==='awaiting_pickup'?<button className="tiny-action" onClick={()=>onPicked(r.id)}>Marcar retirada</button>:'—'}</td>}{page==='reservations'&&<td>{r.status==='pending'?<div className="reservation-actions"><button className="tiny-action" onClick={()=>onDecision(r.id,'approved')}>Aprovar</button><button className="tiny-action reject" onClick={()=>onDecision(r.id,'rejected')}>Recusar</button></div>:'—'}</td>}</tr>)}</tbody></table></div>}

function CommonAreas({rows,loading}:any){return <section className="content-card"><div className="table-toolbar"><div><b>Espaços disponíveis para reserva</b><small>Quiosque, salão de festas, quadras e demais áreas cadastradas.</small></div></div>{loading?<Loading/>:rows.length===0?<Empty/>:<div className="area-card-grid">{rows.map((a:R)=><article className="area-card" key={a.id}><div className="area-card-icon"><Home size={22}/></div><div><b>{a.name}</b><small>{a.area_type||'Área comum'} · {a.capacity? a.capacity+' pessoas':'Capacidade não definida'}</small><p>{a.description||a.rules||'Espaço comum do condomínio.'}</p><span>{a.opening_time?.slice(0,5)||'—'} às {a.closing_time?.slice(0,5)||'—'}</span></div></article>)}</div>}</section>}
function ResidentPortal({profile,userId,onSwitch,onLogout}:any){const [tab,T]=useState('inicio'),[unit,U]=useState<any>(null),[packages,PK]=useState<any[]>([]),[reservations,RS]=useState<any[]>([]),[areas,AR]=useState<any[]>([]),[announcements,AN]=useState<any[]>([]),[notifications,NTF]=useState<any[]>([]),[loading,LD]=useState(true),[modal,MO]=useState(false),[form,FM]=useState<any>({}),[saving,SV]=useState(false),[message,MS]=useState('');const load=async()=>{if(!supabase)return;LD(true);const {data:links}=await supabase.from('apartment_residents').select('apartment_id,apartment:apartments(id,block,number,floor,condominium_id)').eq('profile_id',userId);const rawApartment=links?.[0]?.apartment;const chosen=Array.isArray(rawApartment)?rawApartment[0]||null:rawApartment||null;U(chosen);if(chosen){const [p,r,a,n,not]=await Promise.all([supabase.from('packages').select('*').eq('apartment_id',chosen.id).eq('recipient_profile_id',userId).order('received_at',{ascending:false}).limit(20),supabase.from('reservations').select('*,common_areas(name,area_type)').eq('requested_by',userId).order('starts_at',{ascending:false}).limit(30),supabase.from('common_areas').select('*').eq('condominium_id',chosen.condominium_id).eq('is_active',true).order('name'),supabase.from('announcements').select('*').eq('condominium_id',chosen.condominium_id).eq('is_published',true).order('published_at',{ascending:false}).limit(30),supabase.from('resident_notifications').select('*').eq('recipient_profile_id',userId).order('created_at',{ascending:false}).limit(30)]);PK(p.data||[]);RS(r.data||[]);AR(a.data||[]);AN(n.data||[]);NTF(not.data||[]);}LD(false);};useEffect(()=>{load();},[userId]);const book=async(e:any)=>{e.preventDefault();if(!supabase||!unit)return;SV(true);const start=new Date(`${form.date}T${form.start}:00`),end=new Date(`${form.date}T${form.end}:00`);if(end<=start){MS('O horário final precisa ser posterior ao inicial.');SV(false);return;}const {error}=await supabase.from('reservations').insert({condominium_id:unit.condominium_id,area_id:form.area_id,apartment_id:unit.id,requested_by:userId,starts_at:start.toISOString(),ends_at:end.toISOString(),purpose:form.purpose||null,status:'pending'});if(error)MS(error.message);else{MS('Solicitação enviada. Aguarde a aprovação da administração.');MO(false);FM({});await load();}SV(false);};const unread=notifications.filter((n:any)=>!n.is_read).length;return <div className="resident-shell"><header className="resident-top"><div className="resident-brand"><div className="brand-mark">PF</div><div><b>PORTO FRANKFURT</b><small>ÁREA DO MORADOR</small></div></div><div className="resident-top-actions"><span>{profile?.full_name||'Morador'}</span>{onSwitch&&<button className="soft-btn" onClick={onSwitch}><Shield size={15}/> Administração</button>}<button className="icon-btn" onClick={onLogout}><LogOut size={17}/></button></div></header><main className="resident-content"><section className="resident-hero"><span className="eyebrow">PORTAL DO MORADOR</span><h1>Olá, {profile?.full_name?.split(' ')[0]||'vizinho'} 👋</h1><p>Acompanhe sua unidade, encomendas, reservas e avisos do condomínio.</p><div className="resident-unit"><Building2/><b>{unit?`Bloco ${unit.block} · Apartamento ${unit.number}`:'Unidade não vinculada'}</b></div></section>{message&&<div className="success-banner">{message}<button onClick={()=>MS('')}><X size={15}/></button></div>}<nav className="resident-tabs">{[['inicio','Visão geral'],['encomendas','Encomendas'],['reservas','Reservas'],['comunicados','Comunicados']].map(([k,l])=><button className={tab===k?'active':''} key={k} onClick={()=>T(k)}>{l}{k==='encomendas'&&packages.some((p:any)=>p.status==='awaiting_pickup')&&<i/>}{k==='comunicados'&&unread>0&&<i/>}</button>)}</nav>{loading?<Loading/>:tab==='inicio'?<div className="resident-grid"><button className="resident-tile" onClick={()=>T('encomendas')}><Package/><b>{packages.filter((p:any)=>p.status==='awaiting_pickup').length}</b><span>Encomendas aguardando retirada</span></button><button className="resident-tile" onClick={()=>T('reservas')}><CalendarDays/><b>{reservations.length}</b><span>Reservas e solicitações</span></button><button className="resident-tile" onClick={()=>T('comunicados')}><MessageSquare/><b>{announcements.length+notifications.length}</b><span>Comunicados e avisos</span></button><section className="resident-panel"><div className="section-card-head"><div><b>Últimos comunicados</b><small>Informações da administração</small></div></div>{announcements.slice(0,3).map((a:any)=><article className="resident-list-item" key={a.id}><b>{a.title}</b><small>{a.category} · {date(a.published_at||a.created_at)}</small><p>{a.body}</p></article>)}</section></div>:tab==='encomendas'?<ResidentList title="Minhas encomendas" rows={packages} kind="package"/>:tab==='reservas'?<section className="resident-panel"><div className="section-card-head"><div><b>Minhas reservas</b><small>Solicite quiosque, salão de festas, quadra de futebol e outros espaços.</small></div><button className="primary-btn" onClick={()=>MO(true)}><Plus size={16}/> Nova reserva</button></div><ResidentList rows={reservations} kind="reservation"/></section>:<section className="resident-panel"><div className="section-card-head"><div><b>Comunicados do condomínio</b><small>Avisos gerais e mensagens direcionadas a você.</small></div></div>{announcements.map((a:any)=><article className="resident-list-item" key={a.id}><b>{a.title}</b><small>{a.category} · {date(a.published_at||a.created_at)}</small><p>{a.body}</p></article>)}{notifications.map((n:any)=><article className="resident-list-item notification-resident" key={n.id}><b>{n.title}</b><small>{date(n.created_at)} · {n.is_read?'Lido':'Não lido'}</small><p>{n.body}</p></article>)}</section>}</main>{modal&&<div className="modal-backdrop" onClick={()=>MO(false)}><form className="modal-card" onSubmit={book} onClick={e=>e.stopPropagation()}><div className="modal-head"><div><span className="eyebrow">ÁREAS COMUNS</span><h2>Solicitar reserva</h2></div><button type="button" className="icon-btn" onClick={()=>MO(false)}><X/></button></div><label>Espaço<select required value={form.area_id||''} onChange={e=>FM({...form,area_id:e.target.value})}><option value="">Selecione uma área</option>{areas.map((a:any)=><option key={a.id} value={a.id}>{a.name} · {a.area_type||'Área comum'}</option>)}</select></label><label>Data<input type="date" required min={new Date().toISOString().slice(0,10)} value={form.date||''} onChange={e=>FM({...form,date:e.target.value})}/></label><div className="resident-time-row"><label>Início<input type="time" required value={form.start||''} onChange={e=>FM({...form,start:e.target.value})}/></label><label>Fim<input type="time" required value={form.end||''} onChange={e=>FM({...form,end:e.target.value})}/></label></div><label>Finalidade (opcional)<input value={form.purpose||''} onChange={e=>FM({...form,purpose:e.target.value})} placeholder="Ex.: aniversário, futebol…"/></label><div className="modal-actions"><button type="button" className="soft-btn" onClick={()=>MO(false)}>Cancelar</button><button className="primary-btn" disabled={saving}>{saving?'Enviando…':'Enviar solicitação'}</button></div></form></div>}</div>}
function ResidentList({title,rows,kind}:any){return <section className="resident-panel">{title&&<div className="section-card-head"><div><b>{title}</b></div></div>}{rows.length===0?<Empty/>:rows.map((r:any)=><article className="resident-list-item" key={r.id}><div><b>{kind==='package'?(r.recipient_name||'Encomenda'):r.common_areas?.name||'Reserva'}</b><small>{kind==='package'?`${r.carrier||'Transportadora não informada'} · ${date(r.received_at)}`:`${new Date(r.starts_at).toLocaleString('pt-BR')} até ${new Date(r.ends_at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}`}</small></div><span className={'status-pill '+(r.status==='approved'||r.status==='picked_up'?'good':'warn')}>{status(r.status)}</span></article>)}</section>}
function ParkingBoard({rows,loading}:any){const [filter,setFilter]=useState('all');const filtered=rows.filter((r:R)=>filter==='all'||String(r.status||'available')===filter);const labels:any={available:'Disponível',occupied:'Ocupada',reserved:'Reservada',blocked:'Bloqueada'};return <section className="content-card parking-board"><div className="parking-legend"><span><i className="available"/>Disponível</span><span><i className="occupied"/>Ocupada</span><span><i className="reserved"/>Reservada</span><span><i className="blocked"/>Bloqueada</span></div><div className="parking-filters">{[['all','Todas'],['available','Disponíveis'],['occupied','Ocupadas'],['reserved','Reservadas'],['blocked','Bloqueadas']].map(([v,l])=><button key={v} className={filter===v?'selected':''} onClick={()=>setFilter(v)}>{l}</button>)}</div>{loading?<Loading/>:filtered.length===0?<Empty/>:<div className="parking-grid">{filtered.map((r:R,i:number)=>{const st=r.status||'available';return <article className={'parking-space '+st} key={r.id||i}><div className="parking-space-top"><b>{r.space_code||'Vaga '+(i+1)}</b><span>{labels[st]||status(st)}</span></div><Car size={25}/><small>{r.vehicles?.plate||'Sem veículo associado'}</small><small>{r.apartments?'Bloco '+r.apartments.block+' · Unidade '+r.apartments.number:'Unidade não vinculada'}</small><small>{r.location_description||'Localização não informada'}</small></article>})}</div>}</section>}
function Reports({stats}:any){return <div className="content-card"><div className="section-card-head"><div><b>Indicadores operacionais</b><small>Dados consolidados do condomínio.</small></div><ChartNoAxesCombined/></div>{[['Unidades',stats.units,300],['Moradores',stats.residents,300],['Encomendas',stats.packages,30],['Visitantes',stats.visitors,30],['Reservas',stats.reservations,30],['Ocorrências',stats.occurrences,30]].map(([n,v,m]:any)=><div className="bar-row" key={n}><span>{n}</span><div><i style={{width:Math.min(100,v/m*100)+'%'}}/></div><b>{v}</b></div>)}<button className="soft-btn print-btn" onClick={()=>window.print()}>Imprimir relatório</button></div>}
function ImportPanel(){const [file,setFile]=useState<File|null>(null);return <div className="content-card import-card"><div className="import-icon"><Upload size={28}/></div><h2>Migração de dados</h2><p>Importe dados de outro sistema com mapeamento de campos, validação de registros e revisão antes de gravar. Nenhuma informação será alterada automaticamente.</p><div className="import-steps"><span><b>01</b> Enviar arquivo</span><span><b>02</b> Mapear campos</span><span><b>03</b> Validar dados</span><span><b>04</b> Confirmar</span></div><label className="file-drop"><input type="file" accept=".csv,.xlsx,.xls,.json,.sql,.xml" onChange={e=>setFile(e.target.files?.[0]||null)}/><Upload/><b>{file?file.name:'Selecionar arquivo'}</b><small>CSV, XLSX, JSON, XML ou SQL</small></label><div className="drawer-note"><Shield size={16}/> A importação só será efetivada após revisão e confirmação.</div></div>}
function SettingsPanel({profile,dark,setDark}:any){return <div className="settings-grid"><div className="content-card"><b>Perfil e acesso</b><div className="setting-row"><span>Nome</span><b>{profile?.full_name||'—'}</b></div><div className="setting-row"><span>Perfil</span><b>{profile?.role||'—'}</b></div><div className="setting-row"><span>Status</span><b className="status-pill good">Ativo</b></div></div><div className="content-card"><b>Preferências</b><div className="setting-row"><div><b>Modo escuro</b><small>Personalizar aparência.</small></div><button className={'toggle '+(dark?'on':'')} onClick={()=>setDark(!dark)}><i/></button></div></div></div>}
function Empty(){return <div className="empty-state"><div><ClipboardList/></div><b>Nenhum registro encontrado</b><p>Quando houver informações cadastradas, elas aparecerão aqui.</p></div>}
function Loading(){return <div className="table-loading"><div className="spinner"/>Carregando informações…</div>}
